from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    freq=Counter(v for row in out for v in row)
    bg=freq.most_common(1)[0][0]
    other=[c for c in freq if c!=bg]
    marker=max(other,key=lambda c:freq[c])
    dots=[c for c in other if c not in (marker,4)]
    if not dots: return out
    dot=max(dots,key=lambda c:freq[c])
    points=[(r,c) for r in range(h) for c in range(w) if out[r][c]==dot]

    # Check for marker segments on opposite horizontal edges (top/bottom).
    top=[c for c,v in enumerate(out[0]) if v==marker]
    bottom=[c for c,v in enumerate(out[-1]) if v==marker]
    left=[r for r in range(h) if out[r][0]==marker]
    right=[r for r in range(h) if out[r][-1]==marker]
    if top and bottom:
        tpts=[(r,c) for r,c in points if 0<r<h-1 and c in top]
        bpts=[(r,c) for r,c in points if 0<r<h-1 and c in bottom]
        if tpts or bpts:
            if len(tpts)>=len(bpts):
                target=tpts; coord_target=top; coord_other=bottom; edge=0
            else:
                target=bpts; coord_target=bottom; coord_other=top; edge=h-1
            offsets=sorted(set(c-min(coord_target) for r,c in target))
            if edge==0:
                offsets=[len(coord_other)-1-off for off in offsets]
            for off in offsets:
                c=min(coord_other)+off
                if 0<=c<w:
                    for r in range(1,h-1):
                        if out[r][c]==bg: out[r][c]=dot
            for r,c in target:
                out[r][c]=4
                rr=r+(-1 if edge==0 else 1)
                while 0<rr<h-1:
                    if out[rr][c]==bg: out[rr][c]=dot
                    rr+=(-1 if edge==0 else 1)
            return out
    # Rotated arrangement: marker segments on opposite left/right edges.
    if left and right:
        lpts=[(r,c) for r,c in points if 0<c<w-1 and r in left]
        rpts=[(r,c) for r,c in points if 0<c<w-1 and r in right]
        if lpts or rpts:
            if len(lpts)>=len(rpts):
                target=lpts; coord_target=left; coord_other=right; edge=0
            else:
                target=rpts; coord_target=right; coord_other=left; edge=w-1
            offsets=sorted(set(r-min(coord_target) for r,c in target))
            for off in offsets:
                r=min(coord_other)+off
                if 0<=r<h:
                    for c in range(w):
                        if out[r][c]==bg: out[r][c]=dot
            for r,c in target:
                out[r][c]=4
                cc=c+(-1 if edge==0 else 1)
                while 0<cc<w-1:
                    if out[r][cc]==bg: out[r][cc]=dot
                    cc+=(-1 if edge==0 else 1)
            return out
    return out

